      aliases: ['Profile menu', 'User menu', 'Avatar menu'], use: ['Reaching My Account and Settings: the avatar opens them; settings never has a separate button', 'Header placement (default): the avatar ends the header utilities; the menu opens below', 'Pane placement (placement="pane"): the navigation pane footer shows avatar | name; the same menu opens above', 'density: the Display density choices with their icons in the menu (Compact, Standard, Comfortable)', 'appSettings: { app, href | onSelect } names the application’s settings item ("Asset Manager settings"); an application without settings leaves it out', 'signOut: last, after a divider, with the sign-out icon (default: the sign-in proxy’s sign-out)'], avoid: ['Application actions', 'Both placements on one page'],
