        { leaf: 'Segmented tabs', group: 'Style', name: 'Segmented: a compact switch', lab: { variant: 'segmented' }, text: 'Joined segments at the button height, as SegmentedControl; the open tab takes the selected blue tint.', use: ['Two to four views in a toolbar or a small panel'], avoid: ['Many tabs, or long labels: use Folder'] }
